// =====================================================
// INA226 REGISTER READ
// =====================================================

bool readINA226Register(
  uint8_t reg,
  int16_t &value
) {

  Wire.beginTransmission(
    INA226_ADDRESS
  );

  Wire.write(reg);

  if (
    Wire.endTransmission(false) != 0
  ) {

    return false;
  }

  Wire.requestFrom(
    INA226_ADDRESS,
    (uint8_t)2
  );

  if (
    Wire.available() < 2
  ) {

    return false;
  }

  uint16_t raw =
    ((uint16_t)Wire.read() << 8)
    |
    Wire.read();

  value =
    (int16_t)raw;

  return true;
}

// =====================================================
// READ SHUNT VOLTAGE
// =====================================================

bool readShuntVoltage(
  float &millivolts
) {

  int16_t raw;

  // Register 0x01 =
  // INA226 Shunt Voltage

  if (
    !readINA226Register(
      0x01,
      raw
    )
  ) {

    return false;
  }

  float volts =
    raw *
    INA226_SHUNT_LSB_V;

  millivolts =
    volts * 1000.0;

  return true;
}

// =====================================================
// SORT ADC VALUES
// =====================================================

void sortValues(
  uint32_t values[],
  int count
) {

  for (
    int i = 0;
    i < count - 1;
    i++
  ) {

    for (
      int j = i + 1;
      j < count;
      j++
    ) {

      if (
        values[j] <
        values[i]
      ) {

        uint32_t temp =
          values[i];

        values[i] =
          values[j];

        values[j] =
          temp;
      }
    }
  }
}

// =====================================================
// READ BATTERY VOLTAGE
// =====================================================

float readBatteryVoltage() {

  // Take many readings because the
  // ESP32 ADC is relatively noisy.

  const int SAMPLE_COUNT = 64;

  uint32_t samples[SAMPLE_COUNT];

  for (
    int i = 0;
    i < SAMPLE_COUNT;
    i++
  ) {

    samples[i] =
      analogReadMilliVolts(
        BATTERY_VOLTAGE_PIN
      );

    delayMicroseconds(150);
  }

  // Sort low -> high

  sortValues(
    samples,
    SAMPLE_COUNT
  );

  // Throw away the lowest 12
  // and highest 12 readings.

  const int FIRST_SAMPLE = 12;

  const int LAST_SAMPLE = 52;

  uint32_t total = 0;

  int usedSamples = 0;

  for (
    int i = FIRST_SAMPLE;
    i < LAST_SAMPLE;
    i++
  ) {

    total +=
      samples[i];

    usedSamples++;
  }

  float sensorMillivolts =
    total /
    (float)usedSamples;

  float sensorVolts =
    sensorMillivolts /
    1000.0;

  float calculatedBatteryVoltage =
    sensorVolts *
    VOLTAGE_DIVIDER_RATIO *
    VOLTAGE_CALIBRATION;

  return
    calculatedBatteryVoltage;
}

