void synchronizeBatteryFull() {

  socSynchronized = true;

  remainingAh =
    BATTERY_CAPACITY_AH;

  // Reset session statistics

  sessionUsedAh = 0.0;

  sessionChargedAh = 0.0;

  peakDischarge_A = 0.0;

  peakCharge_A = 0.0;

  sessionStartMillis =
    millis();

  saveBatteryState();
}

// =====================================================
// CALCULATE SOC
// =====================================================

float getSOC() {

  if (
    !socSynchronized
  ) {

    return 0.0;
  }

  return
    (
      remainingAh /
      BATTERY_CAPACITY_AH
    )
    *
    100.0;
}

// =====================================================
// UPDATE BATTERY MONITOR
// =====================================================

void updateBatteryMonitor() {

  unsigned long now =
    millis();

  if (
    now -
    lastSampleMillis <
    SAMPLE_INTERVAL_MS
  ) {

    return;
  }

  unsigned long elapsedMs =
    now -
    lastSampleMillis;

  lastSampleMillis =
    now;

  // ===================================================
  // BATTERY VOLTAGE
  // ===================================================

  rawBatteryVoltage =
    readBatteryVoltage();

  if (
    batteryVoltage ==
    0.0
  ) {

    batteryVoltage =
      rawBatteryVoltage;
  }

  else {

    // Slow voltage smoothing

    const float VOLTAGE_ALPHA =
      0.10;

    batteryVoltage =
      (
        VOLTAGE_ALPHA *
        rawBatteryVoltage
      )
      +
      (
        (1.0 -
         VOLTAGE_ALPHA)
        *
        batteryVoltage
      );
  }

  // ===================================================
  // CURRENT
  // ===================================================

  float newShunt_mV;

  if (
    readShuntVoltage(
      newShunt_mV
    )
  ) {

    shuntVoltage_mV =
      newShunt_mV;

    float shuntVoltage_V =
      shuntVoltage_mV /
      1000.0;

    current_A =
      shuntVoltage_V /
      SHUNT_OHMS;

    // -------------------------------------------------
    // ZERO DEADBAND
    // -------------------------------------------------

    if (
      fabs(current_A) <
      CURRENT_DEADBAND_A
    ) {

      current_A = 0.0;
    }

    // -------------------------------------------------
    // FILTER DISPLAYED CURRENT
    // -------------------------------------------------

    const float CURRENT_ALPHA =
      0.25;

    filteredCurrent_A =
      (
        CURRENT_ALPHA *
        current_A
      )
      +
      (
        (1.0 -
         CURRENT_ALPHA)
        *
        filteredCurrent_A
      );

    // =================================================
    // PEAK DISCHARGE
    //
    // POSITIVE CURRENT = DISCHARGE
    // =================================================

    if (
      current_A >
      peakDischarge_A
    ) {

      peakDischarge_A =
        current_A;
    }

    // =================================================
    // PEAK CHARGE
    //
    // NEGATIVE CURRENT = CHARGE
    // =================================================

    if (
      current_A <
      0.0
    ) {

      float chargeMagnitude =
        -current_A;

      if (
        chargeMagnitude >
        peakCharge_A
      ) {

        peakCharge_A =
          chargeMagnitude;
      }
    }

    // =================================================
    // AMP-HOUR INTEGRATION
    // =================================================

    float elapsedHours =
      elapsedMs /
      3600000.0;

    float deltaAh =
      current_A *
      elapsedHours;

    // -------------------------------------------------
    // POSITIVE = DISCHARGE
    // -------------------------------------------------

    if (
      current_A >
      0.0
    ) {

      sessionUsedAh +=
        deltaAh;
    }

    // -------------------------------------------------
    // NEGATIVE = CHARGE
    // -------------------------------------------------

    else if (
      current_A <
      0.0
    ) {

      sessionChargedAh +=
        -deltaAh;
    }

    // =================================================
    // UPDATE REMAINING BATTERY CAPACITY
    // =================================================

    if (
      socSynchronized
    ) {

      // THIS IS THE IMPORTANT PART:
      //
      // + current = discharge
      //   -> subtract Ah
      //
      // - current = charging
      //   -> subtracting negative Ah
      //      ADDS capacity

      remainingAh -=
        deltaAh;

      remainingAh =
        constrain(
          remainingAh,
          0.0,
          BATTERY_CAPACITY_AH
        );
    }
  }

  // ===================================================
  // POWER
  // ===================================================

  // Positive power = boat consuming battery power
  //
  // Negative power = battery being charged

  power_W =
    batteryVoltage *
    filteredCurrent_A;

  // ===================================================
  // SAVE SOC PERIODICALLY
  // ===================================================

  if (
    socSynchronized &&
    (
      now -
      lastSaveMillis >=
      SAVE_INTERVAL_MS
    )
  ) {

    saveBatteryState();
  }
}

// =====================================================
