void resetSession() {

  sessionUsedAh = 0.0;

  sessionChargedAh = 0.0;

  peakDischarge_A = 0.0;

  peakCharge_A = 0.0;

  sessionStartMillis =
    millis();
}

// =====================================================
// SESSION RUNTIME
// =====================================================

String formatRuntime() {

  unsigned long seconds =
    (
      millis() -
      sessionStartMillis
    )
    /
    1000;

  unsigned long hours =
    seconds /
    3600;

  unsigned long minutes =
    (seconds % 3600) /
    60;

  seconds =
    seconds %
    60;

  char buffer[20];

  snprintf(
    buffer,
    sizeof(buffer),
    "%02lu:%02lu:%02lu",
    hours,
    minutes,
    seconds
  );

  return
    String(buffer);
}

// =====================================================
// BATTERY STATUS
// =====================================================

String batteryStatus() {

  // CONFIRMED:
  // Positive = discharge

  if (
    filteredCurrent_A >
    0.10
  ) {

    return
      "DISCHARGING";
  }

  // CONFIRMED:
  // Negative = charge

  if (
    filteredCurrent_A <
    -0.10
  ) {

    return
      "CHARGING";
  }

  return
    "IDLE";
}

// =====================================================
// LIGHTING
// =====================================================

void showCurrentColor() {

  if (
    !lightsOn
  ) {

    strip.clear();

    strip.show();

    return;
  }

  for (
    int i = 0;
    i < LED_COUNT;
    i++
  ) {

    strip.setPixelColor(
      i,
      strip.Color(
        currentR,
        currentG,
        currentB
      )
    );
  }

  strip.show();
}

void setColor(
  uint8_t r,
  uint8_t g,
  uint8_t b
) {

  currentR = r;

  currentG = g;

  currentB = b;

  lightsOn = true;

  showCurrentColor();
}

